import{_ as a,o as n,c as e,a6 as s}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"HPACK 头部压缩","description":"静态表、动态表、整数与字符串编码、六种字段表示格式，以及为何不用 gzip。","frontmatter":{"title":"HPACK 头部压缩","description":"静态表、动态表、整数与字符串编码、六种字段表示格式，以及为何不用 gzip。","source":"https://daiw.org/manual/http2-3/hpack"},"headers":[],"relativePath":"manual/computer-programming/http2-3/hpack.md","filePath":"manual/computer-programming/http2-3/hpack.md"}'),d={name:"manual/computer-programming/http2-3/hpack.md"};function r(o,t,p,l,i,c){return n(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="hpack-头部压缩" tabindex="-1">HPACK 头部压缩 <a class="header-anchor" href="#hpack-头部压缩" aria-label="Permalink to &quot;HPACK 头部压缩&quot;">​</a></h1><p>静态表、动态表、整数与字符串编码、六种字段表示格式，以及为何不用 gzip。</p><p>RFC 7541。解决 1.1 的头部冗余：同一连接上每个请求都重发 <code>user-agent</code>、<code>cookie</code>、<code>accept</code> 等数百字节的相同内容。</p><h2 id="为什么不用-gzip" tabindex="-1">为什么不用 gzip <a class="header-anchor" href="#为什么不用-gzip" aria-label="Permalink to &quot;为什么不用 gzip&quot;">​</a></h2><p>1.1 时代曾有 <code>Transfer-Encoding</code> 压缩头部的想法，被 <strong>CRIME 攻击</strong>否决：攻击者若能控制部分请求内容，可通过观察压缩后长度逐字节猜出同一上下文中的机密（如 Cookie）——因为 DEFLATE 会把重复串压掉，命中即变短。</p><p>HPACK 的对策：</p><ul><li><strong>不做通用字符串匹配压缩</strong>，改用<strong>索引表</strong>——命中与否只泄露「该字段名值对是否出现过」，粒度远粗于逐字节。</li><li>对敏感字段提供 <strong>Never Indexed</strong> 表示（见下），强制不进动态表。</li><li>字符串用<strong>静态 Huffman 表</strong>而非自适应字典，长度不随上下文历史变化。</li></ul><h2 id="两张表" tabindex="-1">两张表 <a class="header-anchor" href="#两张表" aria-label="Permalink to &quot;两张表&quot;">​</a></h2><p>编解码双方各维护一个<strong>索引空间</strong>，由静态表与动态表拼接而成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>索引 1 .. 61        静态表（只读，规范固定）</span></span>
<span class="line"><span>索引 62 .. 62+n-1   动态表（可增删，最近插入的索引最小）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="静态表" tabindex="-1">静态表 <a class="header-anchor" href="#静态表" aria-label="Permalink to &quot;静态表&quot;">​</a></h3><p>61 个最常见的字段（名或名值对），双方硬编码，<strong>无需传输</strong>。节选：</p><table tabindex="0"><thead><tr><th>索引</th><th>字段名</th><th>值</th></tr></thead><tbody><tr><td>1</td><td><code>:authority</code></td><td>—</td></tr><tr><td>2</td><td><code>:method</code></td><td><code>GET</code></td></tr><tr><td>3</td><td><code>:method</code></td><td><code>POST</code></td></tr><tr><td>4</td><td><code>:path</code></td><td><code>/</code></td></tr><tr><td>6</td><td><code>:scheme</code></td><td><code>https</code></td></tr><tr><td>8</td><td><code>:status</code></td><td><code>200</code></td></tr><tr><td>16</td><td><code>accept-encoding</code></td><td><code>gzip, deflate</code></td></tr><tr><td>28</td><td><code>content-length</code></td><td>—</td></tr><tr><td>32</td><td><code>cookie</code></td><td>—</td></tr><tr><td>58</td><td><code>user-agent</code></td><td>—</td></tr></tbody></table><p>于是 <code>:method: GET</code> 只需 <strong>1 个字节</strong>（索引 2 的编码）。</p><h3 id="动态表" tabindex="-1">动态表 <a class="header-anchor" href="#动态表" aria-label="Permalink to &quot;动态表&quot;">​</a></h3><ul><li><strong>先进先出</strong>，容量以字节计：每项开销 = 名长 + 值长 + <strong>32 字节</strong>（估算的内存开销常量）。</li><li>上限由 <code>SETTINGS_HEADER_TABLE_SIZE</code> 声明（默认 <strong>4096</strong> 字节），编码方可用「动态表大小更新」指令主动调小。</li><li><strong>插入新项时若超容，从表尾逐个淘汰</strong>，直到容纳得下；单项大于全表容量时清空全表且不插入（合法操作，非错误）。</li><li>索引编号随插入<strong>动态偏移</strong>——新插入的项恒为索引 62。</li></ul><p><strong>致命约束</strong>：动态表是<strong>连接级共享状态</strong>，编解码双方必须逐帧保持完全同步。这就是<a href="/Front2Full/manual/computer-programming/http2-3/h2-framing">字段块必须连续发送</a>（中间不得插入其他帧）的根本原因，也是 HPACK 解码错误 <strong>MUST</strong> 以 <code>COMPRESSION_ERROR</code> 关闭<strong>整条连接</strong>（而非单个流）的原因——状态一旦失步，后续全部字段块都会解错。</p><h2 id="整数编码" tabindex="-1">整数编码 <a class="header-anchor" href="#整数编码" aria-label="Permalink to &quot;整数编码&quot;">​</a></h2><p>带 N 位前缀的变长整数（N 由上下文决定，1–8）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>若 值 &lt; 2^N - 1:</span></span>
<span class="line"><span>    直接填入前缀位，结束</span></span>
<span class="line"><span>否则:</span></span>
<span class="line"><span>    前缀位全置 1</span></span>
<span class="line"><span>    剩余量 = 值 - (2^N - 1)</span></span>
<span class="line"><span>    循环: 取低 7 位，若还有更多则最高位置 1，输出该字节</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>例（N=5，值 1337）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1337 &gt;= 31  → 前缀 11111</span></span>
<span class="line"><span>1337 - 31 = 1306</span></span>
<span class="line"><span>1306 = 0b10100011010</span></span>
<span class="line"><span>  低7位 0011010 → 有后续 → 10011010</span></span>
<span class="line"><span>  剩余 1010     → 无后续 → 00001010</span></span>
<span class="line"><span>结果: 11111 10011010 00001010</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h2 id="字符串编码" tabindex="-1">字符串编码 <a class="header-anchor" href="#字符串编码" aria-label="Permalink to &quot;字符串编码&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+---+---+---+---+---+---+---+---+</span></span>
<span class="line"><span>| H |    String Length (7+)     |</span></span>
<span class="line"><span>+---+---------------------------+</span></span>
<span class="line"><span>|  String Data (Length octets)  |</span></span>
<span class="line"><span>+-------------------------------+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><ul><li><code>H=1</code> 表示数据经<strong>静态 Huffman 编码</strong>（规范附录固定的码表，按 HTTP 头部字符频率优化，平均省 20–30%）。</li><li><code>H=0</code> 表示原样字节。</li><li>编码方 <strong>SHOULD</strong> 择短者输出——Huffman 对随机串（如已 Base64 的令牌）可能<strong>更长</strong>。</li><li>Huffman 解码时，末尾填充 <strong>MUST</strong> 是 EOS 符号的前缀且长度 &lt; 8 位；填充超长或出现完整 EOS 编码 → <code>COMPRESSION_ERROR</code>。</li></ul><h2 id="六种字段表示" tabindex="-1">六种字段表示 <a class="header-anchor" href="#六种字段表示" aria-label="Permalink to &quot;六种字段表示&quot;">​</a></h2><p>由首字节的高位比特区分：</p><table tabindex="0"><thead><tr><th>前缀位</th><th>表示</th><th>是否入动态表</th></tr></thead><tbody><tr><td><code>1xxxxxxx</code></td><td><strong>索引字段</strong>：名与值都取自表</td><td>—</td></tr><tr><td><code>01xxxxxx</code></td><td><strong>字面量 + 增量索引</strong>：名可索引可字面量</td><td><strong>是</strong></td></tr><tr><td><code>0000xxxx</code></td><td><strong>字面量，不索引</strong></td><td>否</td></tr><tr><td><code>0001xxxx</code></td><td><strong>字面量，永不索引</strong></td><td>否，且<strong>中间件转发时也不得</strong>索引</td></tr><tr><td><code>001xxxxx</code></td><td><strong>动态表大小更新</strong></td><td>—</td></tr></tbody></table><h3 id="never-indexed-的用途" tabindex="-1">Never Indexed 的用途 <a class="header-anchor" href="#never-indexed-的用途" aria-label="Permalink to &quot;Never Indexed 的用途&quot;">​</a></h3><p><code>0001xxxx</code> 是安全机制：携带敏感值（会话令牌、<code>authorization</code>）的字段应用此表示，保证它<strong>永远不进任何一跳的动态表</strong>。这样即使攻击者能在同连接上注入请求，也无法通过观察压缩后长度来探测该值——这是对 CRIME 类攻击的直接防御。</p><p>代理 <strong>MUST</strong> 在重新编码时保留该语义。</p><h2 id="实际效果" tabindex="-1">实际效果 <a class="header-anchor" href="#实际效果" aria-label="Permalink to &quot;实际效果&quot;">​</a></h2><p>一个典型的浏览器请求头（约 700 字节明文）：</p><table tabindex="0"><thead><tr><th>请求</th><th>HPACK 后</th></tr></thead><tbody><tr><td>第 1 个</td><td>~200 字节（字面量入表 + Huffman）</td></tr><tr><td>第 2 个起</td><td><strong>~10–30 字节</strong>（多数字段命中动态表，只发索引）</td></tr></tbody></table><p>这是 h2 在小请求密集场景下收益最大的部分——100 个请求可省下数万字节的上行流量。</p><h2 id="攻击面" tabindex="-1">攻击面 <a class="header-anchor" href="#攻击面" aria-label="Permalink to &quot;攻击面&quot;">​</a></h2><ul><li><strong>HPACK 炸弹</strong>：构造大量字段引用同一巨大动态表项，解压后膨胀数千倍耗尽内存。缓解：设置 <code>SETTINGS_MAX_HEADER_LIST_SIZE</code>，并在<strong>解码过程中</strong>而非解码后检查累计大小。</li><li><strong>动态表内存</strong>：每条连接都持有一份动态表，服务端需按连接数控制 <code>HEADER_TABLE_SIZE</code>。</li></ul><p>下一篇：<a href="/Front2Full/manual/computer-programming/http2-3/h2-pseudo-headers">伪头字段</a>。</p>`,38)])])}const u=a(d,[["render",r]]);export{g as __pageData,u as default};
